function build(T,id){const row=catalog.find(x=>x.id===id);if(!row)throw new Error('Unknown architecture '+id);const k=makeKit(T);const b=row.source_bounds,s=b.max.map((v,i)=>v-b.min[i]);BUILDERS[id](k,s[0],s[1],s[2]);const object=k.finish(b);object.name=row.title+' / Reforged';return object;}

